/* ═══ TAGLIO LINGUA · IL REGISTRO DELLE LINGUE ═══════════════════
   L'ELENCO UNICO da cui nascono il selettore in Sistema e i controlli.
   Per aggiungere una lingua (es. il polacco):
     1. una riga qui: ["pl","Polski"];
     2. il blocco I18N.pl nel dizionario (tutte le chiavi: interfaccia,
        TAGLIO CHIAVI DINAMICHE, TAGLIO PIANO DI PARTENZA);
     3. una riga in LINGUA_AI (più sotto): pl:"polacco";
     4. i corpi lunghi: GUIDA_XX, NUVIA_XX, NUVIA_FUNZIONI_XX (22_15) —
        finché mancano esce l'italiano, dichiarato dall'avviso;
     5. `node banco/lingua.js pl` dice in ogni momento cosa manca.
   La lingua diventa scelta nel selettore solo quando pronta("pl")
   supera la soglia. ═══════════════════════════════════════════════ */
const LINGUE=[["it","Italiano"],["en","English"]];
window.LINGUE=LINGUE;
let LANG="it";
function langInit(){
  try{
    /* ── LA LINGUA LEGGE LA CASA NUOVA, POI LA VECCHIA (v15.25.0) ──
       langInit gira in 10_base, PRIMA che 11_2 faccia il trasloco:
       chi apre l'app il giorno dell'aggiornamento ha i dati ancora
       solo sotto la chiave vecchia, e leggerne una sola avrebbe
       voluto dire un avvio in inglese per un telefono italiano —
       una volta sola, ma proprio la volta dell'aggiornamento. */
    const salvata=((JSON.parse(localStorage.getItem("nuvia_v3")||"null")
                  ||JSON.parse(localStorage.getItem("diarioDieta_v2")||"{}")).ui||{}).lang;
    if(salvata){LANG=salvata;return;}
    /* Il telefono decide la prima volta, ma SOLO quando la lingua è pronta:
       meglio tutto in italiano che metà e metà. */
    /* La regola: telefono in italiano → italiano. Qualsiasi altra lingua
       → inglese, che è la lingua franca. Non «solo se il telefono è
       inglese»: un tedesco o uno spagnolo capiscono l'inglese, non
       l'italiano. */
    const n=(navigator.language||"it").toLowerCase();
    const pronta=(l)=>I18N[l]&&Object.keys(I18N[l]).length>200;
    if(n.startsWith("it"))LANG="it";
    else LANG=pronta("en")?"en":"it";
  }catch(e){LANG="it";}}
langInit();
/* tr("frase") → la frase nella lingua in uso.
   tr("ho {n} mele",{n:3}) → i segnaposto restano leggibili nel dizionario. */
function tr(frase,vars){
  if(frase==null)return "";        /* una frase che non c'è resta vuota, non «null» */
  let out=String(frase);
  if(LANG!=="it"){
    const d=I18N[LANG];
    if(d&&Object.prototype.hasOwnProperty.call(d,frase))out=d[frase];
  }
  if(vars)Object.keys(vars).forEach(k=>{out=out.split("{"+k+"}").join(vars[k]);});
  return out;}
window.tr=tr;
/* trh: frase intera con dentro dei pezzi di markup («{b}» = una parte in
   grassetto). Serve a non spezzare le frasi in tre chiavi separate: in
   inglese l'ordine delle parole cambia, e il grassetto deve seguirle. */
/* ═══ GIORNI E FASCE: dato in italiano, etichetta tradotta ═══════════
   «Lunedì» e «Colazione» non sono testo qualsiasi: sono VALORI salvati
   nello stato e confrontati dal codice (RICETTE[i].day==="Lunedì", gli slot
   dei pasti, i giorni di mensa). Tradurli alla radice significherebbe non
   riconoscere più i piani già fatti, e cambiare lingua cancellerebbe le
   scelte di chi l'app la usa da mesi.

   Quindi il dato resta italiano e si traduce solo QUANDO SI STAMPA:
   giorno() e fascia() prendono il valore e restituiscono l'etichetta
   nella lingua in uso. Regola: nei confronti e nei salvataggi si usa il
   valore nudo, a schermo si passa sempre da qui. */
function giorno(g){const v=String(g==null?"":g);return v?tr(v):v;}
function fascia(s){
  const v=String(s==null?"":s);
  if(!v)return v;
  /* In turno di notte «Colazione» è una parola sbagliata: qui — e
     solo qui, perché è il punto unico da cui passano i nomi dei
     pasti — diventa «Pasto 1». Il piano non cambia: cambia come lo
     chiamiamo. */
  try{
    if(typeof turnoEtichetta==="function"){
      const e=turnoEtichetta(v);
      if(e)return e;}
  }catch(_){}
  return tr(v);}
/* Le liste dei pasti sono scritte come «Colazione, Pranzo, Cena»: qui si
   traduce voce per voce senza toccare le virgole che le separano. */
function fasce(lista){return String(lista||"").split(",").map(x=>{
  const t=x.trim();return t?x.replace(t,fascia(t)):x;}).join(",");}

function trh(frase,parti){
  let out=tr(frase);
  if(parti)Object.keys(parti).forEach(k=>{out=out.split("{"+k+"}").join(parti[k]);});
  return out;}
window.trh=trh;
/* Il formato di data segue la lingua scelta, non quella del telefono.
   Formato britannico (15/08/2026): giorno-mese-anno come in italiano,
   così le date restano confrontabili fra le due lingue. */
function dataLoc(){return (typeof LANG!=="undefined"&&LANG==="en")?"en-GB":"it-IT";}
window.dataLoc=dataLoc;
/* Decimali: virgola in italiano, punto in inglese (74,5 ↔ 74.5). */
function numLoc(x){const s=String(x);return (typeof LANG!=="undefined"&&LANG==="en")?s:s.replace(".",",");}
window.numLoc=numLoc;

/* Etichette dei PULSANTI: qualche parola italiana vale due cose diverse.
   «Annulla» accanto a un messaggio significa «annulla quello che hai appena
   fatto» (Undo); dentro un dialogo significa «lascia perdere» (Cancel).
   Una sola voce di dizionario non può servirle entrambe, e la chiave deve
   restare l'italiano vero — così in italiano il pulsante resta «Annulla». */
const BTN_EN={"Annulla":"Cancel"};
function trBtn(s){return (LANG==="en"&&BTN_EN[s])?BTN_EN[s]:tr(s);}
window.trBtn=trBtn;
/* Le frasi che l'app userebbe in inglese ma che non sono ancora tradotte:
   servono al collaudo, non all'utente. */
window.i18nMancanti=[];
function tSeg(frase){                /* variante che segna i buchi durante i test */
  if(LANG!=="it"&&!(I18N[LANG]&&Object.prototype.hasOwnProperty.call(I18N[LANG],frase)))
    window.i18nMancanti.push(frase);
  return tr(frase);}
window.tSeg=tSeg;
/* ═══ TAGLIO LINGUA · LA LINGUA DELL'AI ══════════════════════════
   Decisione del founder (25/08): i contenuti seguono la lingua —
   piatti, spesa e risposte comprese. Le ISTRUZIONI dei prompt restano
   in italiano (sono per il modello, non per la persona); questa
   clausola dice al modello in che lingua DEVE scrivere ciò che
   l'utente leggerà. Per una lingua nuova si aggiunge una riga qui. */
const LINGUA_AI={it:"italiano",en:"inglese"};
function aiLingua(){
  const nome=LINGUA_AI[LANG]||LANG;
  if(LANG==="it")return "";          /* il default dei prompt è già l'italiano */
  return " LINGUA DELLA RISPOSTA (vincolante): tutto ciò che l'utente leggerà — nomi dei piatti, descrizioni, contesti dei giorni, voci della spesa, testo libero — va scritto in "+nome+
         ". I nomi dei giorni e dei pasti nel JSON restano ESATTAMENTE quelli richiesti dal contratto.";}
window.aiLingua=aiLingua;

/* ── LE STRUTTURE DA RICUOCERE ──────────────────────────────────
   Alcune strutture a livello di modulo (etichette dell'assistente,
   la mappa delle funzioni, le domande di senso…) contengono tr()
   valutato UNA volta, al caricamento. Cambiando lingua senza
   ricaricare restavano nella lingua vecchia: è il difetto che il
   founder ha visto il 25/08 — app in italiano, mappa delle funzioni
   in inglese. Ogni struttura del genere registra qui il proprio
   costruttore, e il cambio lingua le ricostruisce tutte. */
window.I18N_RIFAI=window.I18N_RIFAI||[];
/* Cambiare lingua è un gesto immediato: si salva la scelta, si
   ricuociono le strutture cotte al caricamento, e si ridisegna. */
window.langSet=(l)=>{
  LANG=(l==="en")?"en":"it";
  try{S.ui.lang=LANG;save();}catch(e){}
  (window.I18N_RIFAI||[]).forEach(f=>{try{f();}catch(e){}});
  try{render(cur);}catch(e){}
  try{toast(tr("Lingua: italiano"));}catch(e){}};
